new:
public func play() {
    self.videoNode?.play()
    self.exteraApplyModPlaybackRate()
}

public func pause() {
    self.videoNode?.pause()
}

// GlowGram mod: round video playback rate from mod settings.
func exteraApplyModPlaybackRate() {
    let speed = ExteraPreferences.standard.value(for: ExteraSettings.roundVideoSpeed)
    if abs(speed - 1.0) > 0.01 {
        self.videoNode?.setBaseRate(Double(speed))
    }
}
